{
  "analysis": "The parallel OCR of 951 frames was extremely slow - only 17 frames completed in ~4 minutes despite 16 parallel jobs. This means tesseract is taking ~14 seconds per frame, making full 5fps OCR impractical. We need a smarter strategy: either crop frames to the terminal text area to speed up OCR, use ffmpeg scene detection to only OCR changed frames, or work more carefully with the existing 1fps OCR data and selectively extract higher-fps frames only around gaps.",
  "plan": "First, time a single tesseract run to confirm speed. Then try cropping a frame to the terminal text region and time OCR on the cropped version to see if it's significantly faster. Also examine the full 1fps command list to understand what we already have and identify gaps.",
  "commands": [
    {
      "keystrokes": "time tesseract /app/frames5/frame_0001.png /tmp/test_ocr 2>/dev/null\n",
      "duration": 20.0
    },
    {
      "keystrokes": "convert /app/frames5/frame_0001.png -crop 1200x650+40+30 +repage /tmp/test_crop.png\n",
      "duration": 0.1
    },
    {
      "keystrokes": "time tesseract /tmp/test_crop.png /tmp/test_crop_ocr 2>/dev/null\n",
      "duration": 20.0
    },
    {
      "keystrokes": "wc -l /app/commands_1fps.txt; cat /app/commands_1fps.txt\n",
      "duration": 0.1
    }
  ],
  "task_complete": false
}
